11	
12	const settingsPath = join(homeRoot, ".claude", "settings.json");
13	
14	interface Hook {
15	  type: "command";
16	  command: string;
17	  statusMessage?: string;
18	}
19	interface HookGroup {
20	  matcher?: string;
21	  hooks: Hook[];
22	}
23	interface Settings {
24	  hooks?: Record<string, HookGroup[]>;
25	  [key: string]: unknown;
26	}
27	
28	const readSettings = async (): Promise<Settings> =>
29	  JSON.parse(await readFile(settingsPath, "utf8")) as Settings;
30	
31	const writeSettings = async (settings: Settings): Promise<void> => {
32	  await mkdir(join(homeRoot, ".claude"), { recursive: true });
33	  await writeFile(settingsPath, JSON.stringify(settings, null, 2), "utf8");
34	};
35	
36	const symbiotEntriesIn = (settings: Settings, event: string): Hook[] =>
37	  (settings.hooks?.[event] ?? [])
38	    .filter((g) => g.matcher === "ExitPlanMode")
39	    .flatMap((g) => g.hooks)
40	    .filter((h) => /run-hook/.test(h.command));
41	
42	describe("installHook", () => {
43	  beforeEach(async () => {
44	    await writeSettings({});
45	  });
46	
47	  it("registers ExitPlanMode under both PreToolUse and PermissionRequest", async () => {
48	    await installHook();
49	    const settings = await readSettings();
50	    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
51	    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
52	    expect(symbiotEntriesIn(settings, "PreToolUse")[0]?.command).toBe(
53	      symbiotEntriesIn(settings, "PermissionRequest")[0]?.command
54	    );
55	  });
56	
57	  it("registers a statusMessage spinner on both events", async () => {
58	    await installHook();
59	    const settings = await readSettings();
60	    expect(symbiotEntriesIn(settings, "PreToolUse")[0]?.statusMessage).toBeTruthy();
61	    expect(symbiotEntriesIn(settings, "PermissionRequest")[0]?.statusMessage).toBeTruthy();
62	  });
63	
64	  it("is idempotent across repeat installs", async () => {
65	    await installHook();
66	    await installHook();
67	    const settings = await readSettings();
68	    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
69	    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
70	  });
71	
72	  it("preserves unrelated hooks under the same events", async () => {
73	    await writeSettings({
74	      hooks: {
75	        PreToolUse: [{ matcher: "Bash", hooks: [{ type: "command", command: "other-cmd" }] }],
76	        PermissionRequest: [{ matcher: "Edit", hooks: [{ type: "command", command: "edit-cmd" }] }],
77	      },
78	    });
79	    await installHook();
80	    const settings = await readSettings();
81	    const preCommands = (settings.hooks?.PreToolUse ?? []).flatMap((g) =>
82	      g.hooks.map((h) => h.command)
83	    );
84	    const permCommands = (settings.hooks?.PermissionRequest ?? []).flatMap((g) =>
85	      g.hooks.map((h) => h.command)
86	    );
87	    expect(preCommands).toContain("other-cmd");
88	    expect(permCommands).toContain("edit-cmd");
89	    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
90	    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
91	  });
92	
93	  it("strips deprecated Stop entries from earlier Phase-2 cuts", async () => {
94	    await writeSettings({
95	      hooks: {
96	        Stop: [
97	          {
98	            hooks: [{ type: "command", command: "bun /tmp/apps/hook/src/cli.ts run-hook" }],
99	          },
100	        ],
101	      },
102	    });
103	    await installHook();
104	    const settings = await readSettings();
105	    expect(symbiotEntriesIn(settings, "Stop")).toHaveLength(0);
106	    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
107	    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
108	  });
109	});
110	
111	describe("uninstallHook", () => {
112	  it("removes symbiot entries from both PreToolUse and PermissionRequest", async () => {
113	    await writeSettings({});
114	    await installHook();
115	    const { removed } = await uninstallHook();
116	    expect(removed).toBe(2);
117	    const settings = await readSettings();
