import { join } from "node:path";

import { beforeEach, describe, expect, it } from "vitest";

const homeRoot = await mkdtemp(join(tmpdir(), "symbiot-installhook-test-"));
process.env.HOME = homeRoot;

const { installHook, uninstallHook } = await import("./installHook.ts");

const settingsPath = join(homeRoot, ".claude", "settings.json");

interface Hook {
  type: "command";
  command: string;
  statusMessage?: string;
}
interface HookGroup {
  matcher?: string;
  hooks: Hook[];
}
interface Settings {
  hooks?: Record<string, HookGroup[]>;
  [key: string]: unknown;
}

const readSettings = async (): Promise<Settings> =>
  JSON.parse(await readFile(settingsPath, "utf8")) as Settings;

const writeSettings = async (settings: Settings): Promise<void> => {
  await mkdir(join(homeRoot, ".claude"), { recursive: true });
  await writeFile(settingsPath, JSON.stringify(settings, null, 2), "utf8");
};

const symbiotEntriesIn = (settings: Settings, event: string): Hook[] =>
  (settings.hooks?.[event] ?? [])
    .filter((g) => g.matcher === "ExitPlanMode")
    .flatMap((g) => g.hooks)
    .filter((h) => /run-hook/.test(h.command));

describe("installHook", () => {
  beforeEach(async () => {
    await writeSettings({});
  });

  it("registers ExitPlanMode under both PreToolUse and PermissionRequest", async () => {
    await installHook();
    const settings = await readSettings();
    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
    expect(symbiotEntriesIn(settings, "PreToolUse")[0]?.command).toBe(
      symbiotEntriesIn(settings, "PermissionRequest")[0]?.command
    );
  });

  it("registers a statusMessage spinner on both events", async () => {
    await installHook();
    const settings = await readSettings();
    expect(symbiotEntriesIn(settings, "PreToolUse")[0]?.statusMessage).toBeTruthy();
    expect(symbiotEntriesIn(settings, "PermissionRequest")[0]?.statusMessage).toBeTruthy();
  });

  it("is idempotent across repeat installs", async () => {
    await installHook();
    await installHook();
    const settings = await readSettings();
    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
  });

  it("preserves unrelated hooks under the same events", async () => {
    await writeSettings({
      hooks: {
        PreToolUse: [{ matcher: "Bash", hooks: [{ type: "command", command: "other-cmd" }] }],
        PermissionRequest: [{ matcher: "Edit", hooks: [{ type: "command", command: "edit-cmd" }] }],
      },
    });
    await installHook();
    const settings = await readSettings();
    const preCommands = (settings.hooks?.PreToolUse ?? []).flatMap((g) =>
      g.hooks.map((h) => h.command)
    );
    const permCommands = (settings.hooks?.PermissionRequest ?? []).flatMap((g) =>
      g.hooks.map((h) => h.command)
    );
    expect(preCommands).toContain("other-cmd");
    expect(permCommands).toContain("edit-cmd");
    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
  });

  it("strips deprecated Stop entries from earlier Phase-2 cuts", async () => {
    await writeSettings({
      hooks: {
        Stop: [
          {
            hooks: [{ type: "command", command: "bun /tmp/apps/hook/src/cli.ts run-hook" }],
          },
        ],
      },
    });
    await installHook();
    const settings = await readSettings();
    expect(symbiotEntriesIn(settings, "Stop")).toHaveLength(0);
    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(1);
    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(1);
  });
});

describe("uninstallHook", () => {
  it("removes symbiot entries from both PreToolUse and PermissionRequest", async () => {
    await writeSettings({});
    await installHook();
    const { removed } = await uninstallHook();
    expect(removed).toBe(2);
    const settings = await readSettings();
    expect(symbiotEntriesIn(settings, "PreToolUse")).toHaveLength(0);
    expect(symbiotEntriesIn(settings, "PermissionRequest")).toHaveLength(0);
  });

  it("reports 0 removed when no symbiot entries exist", async () => {
    await writeSettings({});
    const { removed } = await uninstallHook();
    expect(removed).toBe(0);
  });
});

/**
 * Install / uninstall the symbiot hooks in `~/.claude/settings.json`.
 *
 * A thin binding over the shared {@link createConfigHookInstaller}. Registers the
 * `ExitPlanMode`-matched symbiot group under TWO events:
 *
 *   - `PreToolUse(ExitPlanMode)` — drives the viewer; emits the `decision:"block"`
 *     deny path (bulletproof) and a `permissionDecision:"allow"` approve payload.
 *   - `PermissionRequest(ExitPlanMode)` — defensive workaround for
 *     anthropics/claude-code#50660; reads the approve marker written by the
 *     PreToolUse run and echoes it back so Claude Code can short-circuit its native
 *     "Accept this plan?" prompt.
 *
 * A deprecated `Stop` registration shipped in earlier releases is strip-cleaned.
 * Unlike Codex/Gemini, the entry carries no `timeout` (Claude Code's plugin
 * `hooks/hooks.json` owns that). The `command` points at this app's source
 * `cli.ts` so the embedded viewer's relative `dist/client/` path math stays intact.
 *
 * @see ../../README.md — the hook lifecycle and on-disk shape.
 * @see ../../../packages/symbiot-agent-runtime/src/config-installer.ts — the shared installer.
 */
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

import { createConfigHookInstaller } from "@symbiot/agent-runtime/config-installer";

// Recognize both the current `claude-code` and the historical `hook` workspace path
// (issue #163 rename) so a pre-rename dev install is still stripped on reinstall and
// uninstall; the `symbiot run-hook` literal covers the compiled-binary invocation.
const isSymbiotEntry = (command: string): boolean =>
  /apps\/(?:hook|claude-code)\/(src|dist)\/cli\.(ts|js).*run-hook/.test(command) ||
  command === "symbiot run-hook";

const cliCommand = (): string =>
  `bun ${resolve(dirname(fileURLToPath(import.meta.url)), "cli.ts")} run-hook`;

export const { installHook, uninstallHook } = createConfigHookInstaller({
  path: join(homedir(), ".claude", "settings.json"),
  cliCommand,
  isSymbiotEntry,
  registerEvents: ["PreToolUse", "PermissionRequest"],
  cleanEvents: ["Stop"],
  matcher: "ExitPlanMode",
  entryExtras: { statusMessage: "Symbiot: opening plan reviewer…" },
});

